--
-- IMPORTANT - THIS FILE MUST BE SAVED WITH UTF-8 ENCODING ONLY. BEWARE IF EDITING!
--
-- The News sample data: the Hammond template's news site. Built from a fresh install with the command line (articles,
-- categories, tags, menus and modules), with its images in images/sampledata/news. The installer moves its dates
-- forward, keeping the time between them.
--

TRUNCATE "#__assets" RESTART IDENTITY;
TRUNCATE "#__categories" RESTART IDENTITY;
TRUNCATE "#__content" RESTART IDENTITY;
TRUNCATE "#__content_frontpage" RESTART IDENTITY;
TRUNCATE "#__contentitem_tag_map" RESTART IDENTITY;
TRUNCATE "#__menu" RESTART IDENTITY;
TRUNCATE "#__menu_types" RESTART IDENTITY;
TRUNCATE "#__modules" RESTART IDENTITY;
TRUNCATE "#__modules_menu" RESTART IDENTITY;
TRUNCATE "#__tags" RESTART IDENTITY;
TRUNCATE "#__ucm_base" RESTART IDENTITY;
TRUNCATE "#__ucm_content" RESTART IDENTITY;

--
-- Dumping data for table `#__assets`
--


SELECT setval('#__assets_id_seq', max(id)) FROM "#__assets";

--
-- Dumping data for table `#__categories`
--


SELECT setval('#__categories_id_seq', max(id)) FROM "#__categories";

--
-- Dumping data for table `#__content`
--


SELECT setval('#__content_id_seq', max(id)) FROM "#__content";

--
-- Dumping data for table `#__content_frontpage`
--


--
-- Dumping data for table `#__contentitem_tag_map`
--


--
-- Dumping data for table `#__menu`
