--


--
-- Dumping data for table `#__tags`
--


SELECT setval('#__tags_id_seq', max(id)) FROM "#__tags";

--
-- Dumping data for table `#__ucm_base`
--


SELECT setval('#__ucm_base_ucm_id_seq', max(ucm_id)) FROM "#__ucm_base";

--
-- Dumping data for table `#__ucm_content`
--


SELECT setval('#__ucm_content_core_content_id_seq', max(core_content_id)) FROM "#__ucm_content";

--
-- The Hammond template's settings for the News site
--

UPDATE "#__template_styles" SET "params" = '{"siteName": "Hammond News", "tagline": "Independent journalism on politics, the economy, technology and the ideas shaping our world.", "footerText": "Hammond News is a placeholder publication made for demonstrating Joomla. Hammond Media Ltd., 10 Example Street, Exampletown. Registered in Exampleland, company no. 0000000. All articles, people and figures on this site are fictional.", "pagesMenu": "companymenu", "social_facebook": "#", "social_x": "#", "social_instagram": "#", "social_youtube": "#", "social_linkedin": "#", "social_rss": ""}' WHERE "template" = 'hammond' AND "client_id" = 0;
